import{_ as t,o as a,c as o,a2 as s}from"./chunks/framework.DaAAbehN.js";const u=JSON.parse('{"title":"Lesson 9: Natural Language Driven — Commanding AI by \\"Talking\\"","description":"","frontmatter":{},"headers":[],"relativePath":"en/modules/module-3/lesson-9.md","filePath":"en/modules/module-3/lesson-9.md"}'),n={name:"en/modules/module-3/lesson-9.md"};function i(l,e,r,p,d,h){return a(),o("div",null,[...e[0]||(e[0]=[s(`<h1 id="lesson-9-natural-language-driven-—-commanding-ai-by-talking" tabindex="-1">Lesson 9: Natural Language Driven — Commanding AI by &quot;Talking&quot; <a class="header-anchor" href="#lesson-9-natural-language-driven-—-commanding-ai-by-talking" aria-label="Permalink to &quot;Lesson 9: Natural Language Driven — Commanding AI by &quot;Talking&quot;&quot;">​</a></h1><blockquote><p>📌 <strong>Learning Objectives</strong>: Master the method of writing effective prompts, learn to describe needs in natural language ⏱️ <strong>Estimated Time</strong>: 25 minutes 🎯 <strong>Teaching Rhythm</strong>: Explanation + contrast examples + hands-on practice</p></blockquote><hr><h2 id="i-what-is-vibe-coding" tabindex="-1">I. What is &quot;Vibe Coding&quot;? <a class="header-anchor" href="#i-what-is-vibe-coding" aria-label="Permalink to &quot;I. What is &quot;Vibe Coding&quot;?&quot;">​</a></h2><p><strong>Vibe Coding</strong> is a new term that means: <strong>describe what you want in natural language, and let AI handle the implementation.</strong></p><p>You don&#39;t need to write code. You don&#39;t need to understand technical details. You only need to:</p><ol><li>Clearly know what you want</li><li>Describe it concisely in language</li><li>Let AI implement it</li></ol><h3 id="analogy" tabindex="-1">Analogy <a class="header-anchor" href="#analogy" aria-label="Permalink to &quot;Analogy&quot;">​</a></h3><p>Imagine ordering food at a restaurant:</p><ul><li><strong>Traditional programming</strong>: You need to buy ingredients, wash them, chop them, cook them, and season them — every step by hand</li><li><strong>Vibe Coding</strong>: You tell the chef (Codex) &quot;I want Kung Pao chicken, less spicy,&quot; and the chef handles everything</li></ul><p><strong>You don&#39;t need to know how to cook. You just need to know how to order.</strong></p><hr><h2 id="ii-how-to-write-good-prompts" tabindex="-1">II. How to Write Good &quot;Prompts&quot; <a class="header-anchor" href="#ii-how-to-write-good-prompts" aria-label="Permalink to &quot;II. How to Write Good &quot;Prompts&quot;&quot;">​</a></h2><h3 id="_2-1-bad-prompt-vs-good-prompt" tabindex="-1">2.1 Bad Prompt vs Good Prompt <a class="header-anchor" href="#_2-1-bad-prompt-vs-good-prompt" aria-label="Permalink to &quot;2.1 Bad Prompt vs Good Prompt&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Bad Prompt ❌</th><th>Good Prompt ✅</th><th>Why</th></tr></thead><tbody><tr><td>&quot;Help me make something&quot;</td><td>&quot;Help me build a personal profile webpage with a photo, name, bio, and contact info&quot;</td><td>Specific about what to do</td></tr><tr><td>&quot;Organize the files&quot;</td><td>&quot;Group the documents on my desktop into folders by date&quot;</td><td>Explain the sorting rule</td></tr><tr><td>&quot;Write a program&quot;</td><td>&quot;Write a Python script that reads a CSV file and calculates the average of each column&quot;</td><td>Specify input, processing, and output</td></tr><tr><td>&quot;Change the colors&quot;</td><td>&quot;Change the page&#39;s primary color from red to blue, and make the button background dark blue&quot;</td><td>Specify exactly what to change</td></tr></tbody></table><h3 id="_2-2-four-elements-of-a-good-prompt" tabindex="-1">2.2 Four Elements of a Good Prompt <a class="header-anchor" href="#_2-2-four-elements-of-a-good-prompt" aria-label="Permalink to &quot;2.2 Four Elements of a Good Prompt&quot;">​</a></h3><p>A complete prompt should include these elements:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[Action] + [Object] + [Rules/Requirements] + [Expected Result]</span></span></code></pre></div><p>Examples:</p><ul><li><strong>Action</strong>: Help me organize / Help me create / Help me analyze</li><li><strong>Object</strong>: This folder / This dataset / This webpage</li><li><strong>Rule</strong>: Classify by file type / Remove empty rows / Use blue theme</li><li><strong>Expected result</strong>: Generate a report / Output a summary table / Save to specified location</li></ul><h3 id="_2-3-prompt-templates" tabindex="-1">2.3 Prompt Templates <a class="header-anchor" href="#_2-3-prompt-templates" aria-label="Permalink to &quot;2.3 Prompt Templates&quot;">​</a></h3><p>You can directly use these templates:</p><p><strong>File Operations:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Help me [action] [object], [rule]</span></span>
<span class="line"><span>Example: Help me classify the images in this folder by shooting date.</span></span></code></pre></div><p><strong>Content Generation:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Help me [action] a [type] about [topic], with [specific requirements]</span></span>
<span class="line"><span>Example: Help me write a weekly report on healthy eating, divided into three sections.</span></span></code></pre></div><p><strong>Data Analysis:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Help me analyze [data source], find [focus point], output as [format]</span></span>
<span class="line"><span>Example: Help me analyze this sales data, find the fastest-growing products, output as a table.</span></span></code></pre></div><hr><h2 id="iii-learn-to-follow-up-and-correct" tabindex="-1">III. Learn to &quot;Follow Up&quot; and &quot;Correct&quot; <a class="header-anchor" href="#iii-learn-to-follow-up-and-correct" aria-label="Permalink to &quot;III. Learn to &quot;Follow Up&quot; and &quot;Correct&quot;&quot;">​</a></h2><p>Codex doesn&#39;t always give perfect results on the first try. The key is <strong>learning to follow up</strong>.</p><h3 id="scenario-demo" tabindex="-1">Scenario Demo <a class="header-anchor" href="#scenario-demo" aria-label="Permalink to &quot;Scenario Demo&quot;">​</a></h3><p>Suppose you want Codex to build you a webpage:</p><p><strong>Round 1:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>You: Help me build a personal profile webpage.</span></span>
<span class="line"><span>Codex: Generates a basic webpage.</span></span></code></pre></div><p><strong>Round 2 (you notice an issue):</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>You: The page is too simple. Add a project showcase section.</span></span>
<span class="line"><span>Codex: Adds the project showcase section.</span></span></code></pre></div><p><strong>Round 3 (further optimization):</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>You: Change the primary color to blue and use a larger font.</span></span>
<span class="line"><span>Codex: Modifies the color and font.</span></span></code></pre></div><p><strong>Round 4 (final review):</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>You: Great. Now save the code as index.html.</span></span>
<span class="line"><span>Codex: Save complete.</span></span></code></pre></div><h3 id="key-tips" tabindex="-1">Key Tips <a class="header-anchor" href="#key-tips" aria-label="Permalink to &quot;Key Tips&quot;">​</a></h3><ul><li><strong>Don&#39;t be afraid to say &quot;that&#39;s not right&quot;</strong>: If the result isn&#39;t what you want, tell Codex directly what&#39;s wrong.</li><li><strong>Give specific feedback</strong>: Don&#39;t say &quot;it doesn&#39;t look good.&quot; Say &quot;make the title font bigger&quot; or &quot;add some spacing.&quot;</li><li><strong>Progress step by step</strong>: Break big tasks into small steps and do them one at a time.</li></ul><hr><h2 id="iv-hands-on-let-codex-create-a-webpage-from-your-description" tabindex="-1">IV. Hands-On: Let Codex Create a Webpage from Your Description <a class="header-anchor" href="#iv-hands-on-let-codex-create-a-webpage-from-your-description" aria-label="Permalink to &quot;IV. Hands-On: Let Codex Create a Webpage from Your Description&quot;">​</a></h2><h3 id="task" tabindex="-1">Task <a class="header-anchor" href="#task" aria-label="Permalink to &quot;Task&quot;">​</a></h3><p>Use Codex to create a simple personal profile webpage.</p><h3 id="steps" tabindex="-1">Steps <a class="header-anchor" href="#steps" aria-label="Permalink to &quot;Steps&quot;">​</a></h3><ol><li>Open Codex and create a new workspace (e.g., a &quot;My Webpage&quot; folder on your desktop).</li><li>Type this prompt:<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Help me build a personal profile webpage that includes:</span></span>
<span class="line"><span>- Top: a circular avatar placeholder + name + a one-sentence bio</span></span>
<span class="line"><span>- Middle: a skills list (displayed as tags)</span></span>
<span class="line"><span>- Bottom: contact info (email and social media links)</span></span>
<span class="line"><span>The overall style should be clean and modern, using blue as the primary color.</span></span></code></pre></div></li><li>Observe the HTML code Codex generates.</li><li>Save the code as <code>index.html</code> and open it in a browser to see the result.</li><li>Based on what you see, continue to request modifications.</li></ol><h3 id="possible-follow-up-prompts" tabindex="-1">Possible Follow-Up Prompts <a class="header-anchor" href="#possible-follow-up-prompts" aria-label="Permalink to &quot;Possible Follow-Up Prompts&quot;">​</a></h3><ul><li>&quot;Change the avatar from a circle to a rounded square.&quot;</li><li>&quot;Add a project showcase section below the skills list.&quot;</li><li>&quot;Change the color scheme to dark mode.&quot;</li></ul><hr><h2 id="v-in-lesson-practice-checklist" tabindex="-1">V. In-Lesson Practice Checklist <a class="header-anchor" href="#v-in-lesson-practice-checklist" aria-label="Permalink to &quot;V. In-Lesson Practice Checklist&quot;">​</a></h2><p>Complete the following tasks in order:</p><ul><li>[ ] Try using a &quot;bad prompt&quot; to get Codex to do something, and feel the problem with vague prompts.</li><li>[ ] Rephrase the same task with a &quot;good prompt&quot; and compare the results.</li><li>[ ] Complete the webpage creation hands-on above, with at least 3 rounds of follow-up.</li><li>[ ] Summarize: What do you think is the hardest part of writing prompts?</li></ul><hr><h2 id="vi-summary" tabindex="-1">VI. Summary <a class="header-anchor" href="#vi-summary" aria-label="Permalink to &quot;VI. Summary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Knowledge Point</th><th>Core Content</th></tr></thead><tbody><tr><td>Vibe Coding</td><td>Describe the goal in natural language, let AI handle the rest</td></tr><tr><td>Four elements of a good prompt</td><td>Action + Object + Rules + Expected result</td></tr><tr><td>Follow-up and correction</td><td>Don&#39;t追求 a perfect result on the first try, learn to iteratively optimize</td></tr><tr><td>Prompt templates</td><td>File Operations / Content Generation / Data Analysis three categories</td></tr></tbody></table><hr><h2 id="vii-next-step" tabindex="-1">VII. Next Step <a class="header-anchor" href="#vii-next-step" aria-label="Permalink to &quot;VII. Next Step&quot;">​</a></h2><p><a href="./lesson-10.html">→ Lesson 10: Web Search &amp; Research</a></p>`,61)])])}const g=t(n,[["render",i]]);export{u as __pageData,g as default};
